// En TD : a, b, op saisis avec prompt()
let a = 12;
let b = 0;
let op = "/";   // "+" "-" "*" "/"

let resultat;

if (op == "+") {
    resultat = a + b;
} else if (op == "-") {
    resultat = a - b;
} else if (op == "*") {
    resultat = a * b;
} else if (op == "/") {
    if (b == 0) {
        resultat = "Division par 0 impossible !";
    } else {
        resultat = a / b;
    }
} else {
    resultat = "Operation inconnue";
}

